interactions.sample_code:
function hashAll(keys) {
  for (const k of keys) {
    const i = k % m();        // division method
    note('h(' + k + ') = ' + i);
    insert(k, i);
  }
}

interactions.buggy_code:
function hashAll(keys) {
  for (const k of keys) {
    // BUG: table size hardcoded as 10 instead of m(),
    // so slots go out of range (or are never used) when m changes
    const i = k % 10;
    insert(k, i);
  }
}

